var i=`0580-shakarob`;var n=`world-0580`;var o=`TJ`;var r=`central-asia`;var a=4;var l=29;var s={en:`Shakarob`,ua:`Шакароб`};var c={en:`A traditional dish from Tajikistan, centered on tomato, yellow onion, cucumber, cilantro. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Таджикистан. Основні складники: помідор, жовта цибуля, огірок, кінза. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`tomato`,650,`g`],[`yellow-onion`,190,`g`],[`cucumber`,230,`g`],[`cilantro`,30,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:4,i:[[`extra-virgin-olive-oil`,45,`ml`],[`lemon-juice`,45,`ml`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 15 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 15 хвилин.`,t:[`rapid-chilling`],m:15,i:[]}];var d={slug:i,id:n,country:`TJ`,region:r,servings:4,minutes:29,title:s,text:c,steps:u};export{o as country,d as default,n as id,l as minutes,r as region,a as servings,i as slug,u as steps,c as text,s as title};